package br.com.onda;
import android.app.*;
import android.content.*;
import android.net.Uri;
import android.os.*;
import android.view.*;
import android.widget.*;
import androidx.core.content.FileProvider;
import java.io.*;
import java.net.*;
import java.lang.reflect.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.atomic.*;
import org.json.*;
import org.junit.*;
import static org.junit.Assert.*;
import static androidx.test.platform.app.InstrumentationRegistry.getInstrumentation;
@androidx.media3.common.util.UnstableApi
public class IptvTest {
 private final Instrumentation ins=getInstrumentation();private final Context c=ins.getTargetContext();private Activity activity;private byte[] oldList;private String oldBase;private File fixture;private Instrumentation.ActivityMonitor monitor;
 @Before public void before()throws Exception{File f=IptvStore.file(c);oldList=f.exists()?java.nio.file.Files.readAllBytes(f.toPath()):null;oldBase=c.getSharedPreferences("iptv",0).getString("base","");}
 @After public void after()throws Exception{if(monitor!=null)ins.removeMonitor(monitor);if(activity!=null){ins.runOnMainSync(activity::finish);ins.waitForIdleSync();}if(oldList==null)IptvStore.file(c).delete();else java.nio.file.Files.write(IptvStore.file(c).toPath(),oldList);c.getSharedPreferences("iptv",0).edit().putString("base",oldBase).commit();if(fixture!=null)fixture.delete();}
 private Object field(Object o,String n)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}
 private interface Check{boolean ready()throws Exception;}
 private void waitFor(Check check)throws Exception{boolean[] done={false};for(int i=0;i<600;i++){ins.runOnMainSync(()->{try{done[0]=check.ready();}catch(Exception e){throw new RuntimeException(e);}});if(done[0])return;Thread.sleep(50);}fail("IPTV scenario timed out");}
 private void report(String part,JSONObject data)throws Exception{try(OutputStream out=new FileOutputStream(new File(c.getFilesDir(),"iptv-"+part+".json"))){out.write(data.toString(2).getBytes("UTF-8"));}}
 private void screenshot(String part)throws Exception{android.graphics.Bitmap image=ins.getUiAutomation().takeScreenshot();if(image!=null)try(OutputStream out=new FileOutputStream(new File(c.getFilesDir(),"iptv-"+part+".png"))){image.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);image.recycle();}}
 @Test public void httpsListFilePickerSearchAndFailedReplacementPreserveValidList()throws Exception{List<IptvPlaylist.Channel> fetched=IptvStore.download(c,"https://raw.githubusercontent.com/cristianoarakaki-cpu/Arakaki/main/Onda/tests/fixtures/iptv-test.m3u");assertEquals(2,fetched.size());byte[] valid=java.nio.file.Files.readAllBytes(IptvStore.file(c).toPath());try{IptvStore.save(c,new ByteArrayInputStream("<html>Login</html>".getBytes()),"");fail();}catch(IOException expected){}assertArrayEquals(valid,java.nio.file.Files.readAllBytes(IptvStore.file(c).toPath()));File dir=new File(c.getCacheDir(),"shares");dir.mkdirs();fixture=File.createTempFile("onda-iptv-",".m3u",dir);java.nio.file.Files.write(fixture.toPath(),valid);Uri uri=FileProvider.getUriForFile(c,c.getPackageName()+".share",fixture);AtomicReference<Intent> player=new AtomicReference<>();monitor=new Instrumentation.ActivityMonitor(){@Override public Instrumentation.ActivityResult onStartActivity(Intent i){if(Intent.ACTION_OPEN_DOCUMENT.equals(i.getAction()))return new Instrumentation.ActivityResult(Activity.RESULT_OK,new Intent().setData(uri));if(i.getComponent()!=null&&i.getComponent().getClassName().equals(IptvPlayerActivity.class.getName())){player.set(i);return new Instrumentation.ActivityResult(Activity.RESULT_CANCELED,null);}return null;}};ins.addMonitor(monitor);activity=ins.startActivitySync(new Intent(c,IptvActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitFor(()->((List<?>)field(activity,"channels")).size()==2);ins.runOnMainSync(()->{try{((Button)field(activity,"file")).performClick();}catch(Exception e){throw new RuntimeException(e);}});waitFor(()->!((Boolean)field(activity,"loading"))&&c.getSharedPreferences("iptv",0).getString("base","x").isEmpty());ins.runOnMainSync(()->{try{((EditText)field(activity,"search")).setText("teste B");}catch(Exception e){throw new RuntimeException(e);}});waitFor(()->((List<?>)field(activity,"shown")).size()==1);screenshot("import");ins.runOnMainSync(()->{try{ListView list=(ListView)field(activity,"list");list.performItemClick(null,0,0);}catch(Exception e){throw new RuntimeException(e);}});waitFor(()->player.get()!=null);assertEquals("https://example.org/test-b.m3u8",player.get().getStringExtra("url"));report("import",new JSONObject().put("httpsPlaylistFetched",true).put("filePickerImport",true).put("searchSelectsCorrectChannel",true).put("invalidImportKeepsPreviousList",true));}
 private final class Server implements AutoCloseable {final ServerSocket server;final Thread thread;final AtomicInteger requests=new AtomicInteger();volatile boolean running=true;final byte[] data;Server()throws Exception{try(InputStream in=ins.getContext().getAssets().open("iptv-channel.ts");ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);data=out.toByteArray();}server=new ServerSocket(0,20,InetAddress.getByName("127.0.0.1"));thread=new Thread(()->{while(running)try(Socket socket=server.accept()){socket.setSoTimeout(5000);BufferedReader input=new BufferedReader(new InputStreamReader(socket.getInputStream(),StandardCharsets.US_ASCII));String first=input.readLine(),line;byte[] payload=first!=null&&first.contains(".m3u8")?("#EXTM3U\n#EXT-X-VERSION:3\n#EXT-X-TARGETDURATION:25\n#EXT-X-MEDIA-SEQUENCE:0\n#EXTINF:25.000,\nchannel.ts\n#EXT-X-ENDLIST\n").getBytes(StandardCharsets.UTF_8):data;String mime=payload==data?"video/mp2t":"application/vnd.apple.mpegurl";int start=0;while((line=input.readLine())!=null&&!line.isEmpty())if(line.toLowerCase(Locale.ROOT).startsWith("range: bytes=")){String raw=line.substring(line.indexOf('=')+1).split("-",2)[0];if(!raw.isEmpty())start=Integer.parseInt(raw);}start=Math.max(0,Math.min(start,payload.length-1));requests.incrementAndGet();String headers="HTTP/1.1 "+(start>0?"206 Partial Content":"200 OK")+"\r\nContent-Type: "+mime+"\r\nAccept-Ranges: bytes\r\nContent-Length: "+(payload.length-start)+"\r\n"+(start>0?"Content-Range: bytes "+start+"-"+(payload.length-1)+"/"+payload.length+"\r\n":"")+"Connection: close\r\n\r\n";OutputStream out=socket.getOutputStream();out.write(headers.getBytes(StandardCharsets.US_ASCII));if(first!=null&&!first.startsWith("HEAD "))out.write(payload,start,payload.length-start);out.flush();}catch(Exception ignored){}});thread.start();}String url(){return "http://127.0.0.1:"+server.getLocalPort()+"/channel.m3u8";}public void close()throws Exception{running=false;server.close();thread.join(6000);}}
 @Test public void nativeHttpHlsChannelProducesVideoAndStopsWhenLeaving()throws Exception{try(Server server=new Server()){activity=ins.startActivitySync(new Intent(c,IptvPlayerActivity.class).putExtra("url",server.url()).putExtra("title","Canal de teste local").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));waitFor(()->((Long)field(activity,"frames"))>0&&((org.videolan.libvlc.MediaPlayer)field(activity,"video")).isPlaying()&&((org.videolan.libvlc.MediaPlayer)field(activity,"video")).getTime()>700);screenshot("player");ins.runOnMainSync(()->{assertEquals(android.content.res.Configuration.ORIENTATION_LANDSCAPE,activity.getResources().getConfiguration().orientation);assertTrue((activity.getWindow().getAttributes().flags&WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON)!=0);try{Method pause=IptvPlayerActivity.class.getDeclaredMethod("onPause"),stop=IptvPlayerActivity.class.getDeclaredMethod("onStop");pause.setAccessible(true);stop.setAccessible(true);pause.invoke(activity);stop.invoke(activity);}catch(Exception e){throw new RuntimeException(e);}});waitFor(()->!((org.videolan.libvlc.MediaPlayer)field(activity,"video")).isPlaying());Thread.sleep(300);int requests=server.requests.get();Thread.sleep(1200);assertEquals(requests,server.requests.get());ins.runOnMainSync(()->assertEquals(0,activity.getWindow().getAttributes().flags&WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON));report("player",new JSONObject().put("nativeHttpHlsVideoFrames",true).put("landscapeFullscreen",true).put("noMoreRequestsAfterLeaving",true).put("screenAwakeFlagReleased",true));}}
}
